import java.util.Scanner;

public class Main {
    static long x, y, n;
    static long minA = -1, minB = -1;

    static void updateMin(long a, int b) {
        if (a < 0) return;
        if (minA == -1) {
            minA = a;
            minB = b;
            return;
        }
        long diff1 = Math.abs(minB * x - minA * y) * b;
        long diff2 = Math.abs(b * x - a * y) * minB;
        if (diff1 > diff2) {
            minA = a;
            minB = b;
        } else if (diff1 == diff2 && (b < minB || (b == minB && a < minA))) {
            minA = a;
            minB = b;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        x = sc.nextLong();
        y = sc.nextLong();
        n = sc.nextLong();

        for (int i = 1; i <= n; i++) {
            long base = i * x / y;
            updateMin(base - 1, i);
            updateMin(base, i);
            updateMin(base + 1, i);
        }
        System.out.println(minA + "/" + minB);
        sc.close();
    }
}
